import { readCsv } from '../lib/csv.js'

const STATES = new Set(['Unread', 'Archive'])

export function instapaperLinks(text) {
  return readCsv(text).rows.map((row) => {
    const savedAt = new Date(Number(row.Timestamp) * 1000).toISOString()
    return {
      url: row.URL,
      title: row.Title,
      savedAt,
      readAt: row.Folder === 'Archive' ? savedAt : null,
      tags: ['imported:instapaper', ...(STATES.has(row.Folder) ? [] : [`folder:${row.Folder}`])],
      highlights: row.Selection ? [{ text: row.Selection, source: 'import' }] : [],
    }
  })
}

export function omnivoreLinks(text) {
  return JSON.parse(text).map((item) => ({
    url: item.url,
    title: item.title,
    savedAt: item.savedAt,
    readAt: item.state === 'Archived' ? item.savedAt : null,
    tags: ['imported:omnivore', ...item.labels],
    highlights: item.highlights.map((h) => ({ text: h.quote, note: h.annotation, source: 'import' })),
  }))
}

export const rows = (text) => text.split('\n').slice(1).map((line) => line.split(','))

